// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        vm.deal(address(c), value);
        vm.prank(c.owner());
        uint256 balanceBefore = address(c).balance;
        bool ok = true;
        try c.sendMoney(target, value, data) {} catch { ok = false; }
        if (ok) {
            assertEq(address(c).balance, balanceBefore - value, "balance reduced by value");
        } else {
            assertEq(address(c).balance, balanceBefore, "balance unchanged on revert");
        }
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
